import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Discord","description":"","frontmatter":{},"headers":[],"relativePath":"channels/discord.md","filePath":"channels/discord.md"}'),n={name:"channels/discord.md"};function o(r,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h1><p>Discord connects through the Discord Gateway with a bot token. It supports private messages, guild channels and threads. A public HTTP webhook is not required for message delivery.</p><h2 id="create-an-app-and-obtain-the-bot-token" tabindex="-1">Create an app and obtain the bot token <a class="header-anchor" href="#create-an-app-and-obtain-the-bot-token" aria-label="Permalink to &quot;Create an app and obtain the bot token&quot;">​</a></h2><p>You need a Discord account, permission to install a bot in a test server, and an existing gateway agent.</p><ol><li>In the <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Developer Portal</a>, create an application.</li><li>Open <strong>Bot</strong>. Under <strong>Token</strong>, generate/reset the bot token and copy it securely.</li><li>On the same page, enable <strong>Message Content Intent</strong> under privileged intents. The receiver needs message content; verified applications may require Discord approval for privileged intents.</li><li>Configure the application&#39;s server installation, including the <code>bot</code> scope. Grant <strong>View Channel</strong>, <strong>Read Message History</strong> and <strong>Send Messages</strong>. If you enable automatic threads, also grant <strong>Create Public Threads</strong> and <strong>Send Messages in Threads</strong>.</li><li>Use the application&#39;s installation link to add it to your test server. Check channel permission overrides as well as the server role.</li></ol><p>Discord&#39;s <a href="https://docs.discord.com/developers/quick-start/getting-started" target="_blank" rel="noreferrer">getting-started guide</a> covers token creation, intents and installation. The gateway uses the bot token; an Application ID, client secret or public key does not substitute for it.</p><h2 id="connect-and-test" tabindex="-1">Connect and test <a class="header-anchor" href="#connect-and-test" aria-label="Permalink to &quot;Connect and test&quot;">​</a></h2><p>Run <code>claude-gateway agents update --agent assistant</code> and choose Discord, or add this fragment to the existing agent configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;discord&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;botToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${DISCORD_BOT_TOKEN}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Set the referenced variable in the gateway environment and restart after manual edits. The receiver reads <code>DISCORD_AUTO_THREAD=true</code> from its environment to enable automatic thread creation. Although <code>autoThread</code> appears in the configuration type, the receiver does not map that JSON field to its environment; use the environment setting. The management API credential field is <code>discord_bot_token</code> on <code>PATCH /api/v1/agents/:agentId</code>.</p><p>DM the bot, allowing direct messages from the shared server if needed. Then approve the request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pending</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discord</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discord</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_CODE</span></span></code></pre></div><p>Send a second DM to verify a complete reply. For a guild, send a delivered message, inspect the guild pairing request in channel settings/pending, approve it, and test with an explicit bot mention.</p><h2 id="access-rules" tabindex="-1">Access rules <a class="header-anchor" href="#access-rules" aria-label="Permalink to &quot;Access rules&quot;">​</a></h2><p>Active rules live in <code>&lt;workspace&gt;/.discord-state/access.json</code>. Use channel settings or the policy API for routine changes. An explicit policy file can contain:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dmPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pairing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allowFrom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;groupPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;guildAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;channelAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;roleAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requireMention&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use string Discord user, guild, channel and role IDs, never names. Discord&#39;s Developer Mode enables <strong>Copy ID</strong> actions. DM approvals populate <code>allowFrom</code>; guild approvals populate <code>guildAllowlist</code>. Preserve existing policy and pending entries when editing.</p><p>The guild policy runs before optional <code>channelAllowlist</code> and <code>roleAllowlist</code> filters. Empty optional filter lists add no extra restriction. Those two filters are backend settings without dedicated web controls. The group mention gate accepts an explicit bot mention or reply to the bot. DMs do not use the mention gate.</p><p><code>discord.dmPolicy</code>, <code>dmAllowlist</code>, <code>guildAllowlist</code> and <code>channelAllowlist</code> in the agent configuration supply receiver initialization values; inspect the effective <code>access.json</code> before changing a running installation. Existing policy files preserve historical behavior during migration: old empty guild allowlists may remain open, and an older policy may not require a mention. New deployments should set their intended policy explicitly. <code>pairing</code> is a separate boolean, not a new value of <code>dmPolicy</code>.</p><p>In an agent session with the Discord access skill, <code>/gateway:discord-access dm-pairing off</code> stops inviting unknown DM senders. This is an agent-session command, not a Discord slash-command registration.</p><h2 id="commands-and-supported-behavior" tabindex="-1">Commands and supported behavior <a class="header-anchor" href="#commands-and-supported-behavior" aria-label="Permalink to &quot;Commands and supported behavior&quot;">​</a></h2><p>Use <code>/help</code> in a private conversation to discover the receiver&#39;s commands. <code>/model</code> and <code>/models</code> list the available models; <code>/model &lt;id or alias&gt;</code> selects a listed model in DMs. Model changes affect the whole agent and restart its sessions, so switching is restricted to direct messages. Guild delivery still requires the bot&#39;s permissions and all configured access filters.</p><h2 id="voice-notes-and-task-controls" tabindex="-1">Voice notes and task controls <a class="header-anchor" href="#voice-notes-and-task-controls" aria-label="Permalink to &quot;Voice notes and task controls&quot;">​</a></h2><p>With <code>gateway.orchestration: true</code>, Discord registers native <code>/voice</code>, <code>/voices</code> and <code>/tasks</code> controls alongside session commands. Buttons operate on the current user/session without invoking the model. <code>/tasks</code> shows pending work and task-specific stop controls; <code>/session</code> and <code>/sessions</code> provide direct session management.</p><p>Configure <a href="/claude-gateway/guide/voice.html">agent voice</a> to transcribe audio attachments and generate spoken acknowledgements/replies. <code>/voice on</code>, <code>/voice auto</code> and <code>/voice off</code> choose Always, voice-input-only and Off. Each chat starts Off; enable the agent&#39;s voice settings and separately select the desired chat mode. <code>/voices</code> selects from the configured provider catalog. Spoken replies are MP3 attachments in the originating channel/thread. Typing continues during queued/running agent or worker activity and stops when only user-input/reconciliation waits remain.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Bot will not connect</td><td>Correct bot token; check intent errors in the gateway log</td></tr><tr><td>Bot online but no useful message content</td><td>Enable Message Content Intent in the Developer Portal and reconnect</td></tr><tr><td>DM works but guild does not</td><td>Guild approval, View Channel/Read Message History, channel/role filters and mention gate</td></tr><tr><td>Receives messages but cannot reply</td><td>Send Messages and channel overrides</td></tr><tr><td>Thread creation/reply fails</td><td><code>DISCORD_AUTO_THREAD=true</code> plus Create Public Threads and Send Messages in Threads permissions</td></tr><tr><td>Policy differs after an upgrade</td><td>Review the migrated <code>.discord-state/access.json</code>; old behavior is preserved</td></tr></tbody></table><p>Implementation references: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/discord/receiver.ts" target="_blank" rel="noreferrer">Discord receiver</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/mcp/tools/discord/access.ts" target="_blank" rel="noreferrer">access module</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/types.ts" target="_blank" rel="noreferrer">configuration types</a>.</p>`,28)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
